-- Levels of bimestre III. Columns: MAT-C1, MAT-C2, COM-C1, COM-C2, ING-C1, ING-C2, CYT-C1, CYT-C2, EPT-C1.
insert into competency_term_levels
  (tenant_id, student_id, competency_id, academic_year_id, term_id, class_id, scale_level_id, asserted_by_id)
select 'a0000000-0000-4000-8000-000000000001', s.student::uuid, c.competency::uuid,
       'a0000000-0000-4000-8000-000000000030', 'a0000000-0000-4000-8000-000000000233', c.class::uuid, sl.id,
       'a0000000-0000-4000-8000-000000000011'
  from (values
    ('a0000000-0000-4000-8000-000000000301', array['A', 'A', 'A', 'B', 'A', 'A', 'B', 'B', 'B']),  -- Julia
    ('a0000000-0000-4000-8000-000000000302', array['B', 'B', 'B', 'B', 'B', 'B', 'B', 'B', 'B']),  -- Kiara
    ('a0000000-0000-4000-8000-000000000303', array['A', 'A', 'A', 'A', 'A', 'A', 'A', 'C', 'A']),  -- Luis
    ('a0000000-0000-4000-8000-000000000304', array['C', 'A', 'C', 'B', 'C', 'A', 'C', 'B', 'A'])   -- Marta
  ) as s(student, levels)
  cross join lateral (values
    (1, 'a0000000-0000-4000-8000-000000000060', 'a0000000-0000-4000-8000-000000000380'),
    (2, 'a0000000-0000-4000-8000-000000000061', 'a0000000-0000-4000-8000-000000000380'),
    (3, 'a0000000-0000-4000-8000-000000000260', 'a0000000-0000-4000-8000-000000000381'),
    (4, 'a0000000-0000-4000-8000-000000000261', 'a0000000-0000-4000-8000-000000000381'),
    (5, 'a0000000-0000-4000-8000-000000000262', 'a0000000-0000-4000-8000-000000000382'),
    (6, 'a0000000-0000-4000-8000-000000000263', 'a0000000-0000-4000-8000-000000000382'),
    (7, 'a0000000-0000-4000-8000-000000000264', 'a0000000-0000-4000-8000-000000000383'),
    (8, 'a0000000-0000-4000-8000-000000000265', 'a0000000-0000-4000-8000-000000000383'),
    (9, 'a0000000-0000-4000-8000-000000000266', 'a0000000-0000-4000-8000-000000000384')
  ) as c(pos, competency, class)
  join grade_scale_levels sl
    on sl.tenant_id = 'a0000000-0000-4000-8000-000000000001' and sl.code = s.levels[c.pos];
